import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.DekDpfFM.js";const E=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"loom","text":"Your C++ kernel, as a function of your framework","tagline":"Write the inner loop once, in plain C++ or CUDA. loom compiles it, hands it the arrays of Jax, Torch, NumPy or CuPy, runs it inside jit, vmap and grad, and gives you the gradient you wrote for it.","actions":[{"theme":"brand","text":"What loom is","link":"/guide/what-is-loom"},{"theme":"alt","text":"Why it is not trivial","link":"/guide/why-not-trivial"},{"theme":"alt","text":"Tutorials","link":"/tutorials/"},{"theme":"alt","text":"GitHub","link":"https://github.com/hleclerc/loom"}]},"features":[{"icon":"🧵","title":"Two worlds, one boundary","details":"Outside, your users keep their framework: Jax, Torch, NumPy or CuPy arrays in, the same kind out. Inside, every value is a loom tensor, whoever owns its buffer, so your code is written once, clearly, for all of them.","link":"/guide/tensors","linkText":"Tensors"},{"icon":"↩️","title":"The adjoint is a kernel like any other","details":"You write the backward in the same C++, loom wires it into jax.custom_vjp or torch.autograd.Function, and loom.testing.check_grad checks it against finite differences.","link":"/guide/adjoint","linkText":"The adjoint"},{"icon":"📦","title":"Compiled on demand, or shipped precompiled","details":"The first call compiles and caches. For a wheel, a script of your package fills a catalogue ahead of time, one directory per architecture, so a user with no compiler still gets the kernels.","link":"/guide/compilation","linkText":"Compilation"},{"icon":"🧭","title":"A kernel that never counts dimensions","details":"Coordinates are read by name: coords[axis], coords + axis, coords.axes - batch_axes. The same body runs in 2-D and in 3-D, batched or not, and a vmap adds an axis without the kernel knowing.","link":"/guide/axes","linkText":"Axes"},{"icon":"🎭","title":"The role is said on the value","details":"loom.out( x ), loom.mutable( x ), loom.scratch( x ): what the kernel reads, writes or only borrows is written where the argument is passed, not in a list on the side that rots.","link":"/guide/arguments","linkText":"Roles"},{"icon":"📏","title":"Sizes the host learns at run time","details":"A kernel counts, the host reads the count, the next buffer is allocated exactly. Under jit, where XLA alone would need a bound chosen before tracing. This is what CsrTensor is made of.","link":"/guide/dynamic-sizes","linkText":"Dynamic sizes"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1794312142000}'),n={name:"index.md"};function l(h,s,r,p,k,o){return a(),e("div",null,[...s[0]||(s[0]=[t("",9)])])}const g=i(n,[["render",l]]);export{E as __pageData,g as default};
